-- GUSTAVO HUB - OBFUSCATED MULTI-HUB
-- Key gate + script selector.

local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")
local LocalPlayer = Players.LocalPlayer

local API = "https://gustavo-hub-api.errpila.workers.dev"
local RECHECK = 30
_G.GustavoHubLicenseRevoked = false

local function requestFn()
    if typeof(request) == "function" then return request end
    if typeof(http_request) == "function" then return http_request end
    if syn and typeof(syn.request) == "function" then return syn.request end
    if fluxus and typeof(fluxus.request) == "function" then return fluxus.request end
end

local function validate(key)
    local req = requestFn()
    if not req then return false, "Executor sem suporte HTTP." end
    local ok, res = pcall(function()
        return req({
            Url = API .. "/validate?key=" .. HttpService:UrlEncode(key),
            Method = "GET",
            Headers = { ["Accept"] = "application/json", ["Cache-Control"] = "no-cache" }
        })
    end)
    if not ok or not res then return false, "Não foi possível contactar o servidor." end
    local code = tonumber(res.StatusCode or res.Status or 0)
    if code ~= 200 then return false, "Key inválida, expirada ou revogada." end
    local body = res.Body or res.body
    if not body then return false, "Resposta inválida." end
    local decodedOk, data = pcall(function() return HttpService:JSONDecode(body) end)
    if not decodedOk or type(data) ~= "table" then return false, "Resposta inválida." end
    if data.valid ~= true then
        if data.reason == "expired" then return false, "Esta key expirou." end
        if data.reason == "revoked" then return false, "Esta key foi revogada." end
        if data.reason == "key_not_found" then return false, "Esta key não existe." end
        if data.reason == "already_used" then return false, "Esta key já foi utilizada." end
        return false, "Key inválida."
    end
    return true, data.expiresAt, data.oneTime == true
end

local function ui(parent, class, props)
    local o=Instance.new(class)
    for k,v in pairs(props or {}) do o[k]=v end
    o.Parent=parent
    return o
end

local function rounded(o,r)
    local c=Instance.new("UICorner")
    c.CornerRadius=UDim.new(0,r or 12)
    c.Parent=o
end

local function makeGui(name)
    local old=game:GetService("CoreGui"):FindFirstChild(name)
    if old then old:Destroy() end
    local g=Instance.new("ScreenGui")
    g.Name=name
    g.ResetOnSpawn=false
    g.IgnoreGuiInset=true
    g.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
    local ok=pcall(function() g.Parent=game:GetService("CoreGui") end)
    if not ok or not g.Parent then g.Parent=LocalPlayer:WaitForChild("PlayerGui") end
    return g
end

local function keyGui()
    local g=makeGui("GustavoHubKeyGate")
    local main=ui(g,"Frame",{Size=UDim2.fromOffset(440,280),Position=UDim2.new(.5,-220,.5,-140),BackgroundColor3=Color3.fromRGB(10,11,16),BorderSizePixel=0})
    rounded(main,16)
    ui(main,"TextLabel",{Size=UDim2.new(1,-40,0,32),Position=UDim2.fromOffset(20,20),BackgroundTransparency=1,Text="GUSTAVO HUB",TextColor3=Color3.fromRGB(242,244,250),TextSize=23,Font=Enum.Font.GothamBold,TextXAlignment=Enum.TextXAlignment.Left})
    ui(main,"TextLabel",{Size=UDim2.new(1,-40,0,25),Position=UDim2.fromOffset(20,55),BackgroundTransparency=1,Text="Introduza a sua key para continuar",TextColor3=Color3.fromRGB(135,141,155),TextSize=12,Font=Enum.Font.Gotham,TextXAlignment=Enum.TextXAlignment.Left})
    local box=ui(main,"TextBox",{Size=UDim2.new(1,-40,0,48),Position=UDim2.fromOffset(20,94),BackgroundColor3=Color3.fromRGB(22,24,33),BorderSizePixel=0,Text="",PlaceholderText="GH-XXXXX-XXXXX-XXXXX",PlaceholderColor3=Color3.fromRGB(100,105,118),TextColor3=Color3.fromRGB(242,244,250),TextSize=14,Font=Enum.Font.Gotham,ClearTextOnFocus=false})
    rounded(box,10)
    ui(main,"UIPadding",{PaddingLeft=UDim.new(0,14),PaddingRight=UDim.new(0,14)})
    local btn=ui(main,"TextButton",{Size=UDim2.new(1,-40,0,44),Position=UDim2.fromOffset(20,153),BackgroundColor3=Color3.fromRGB(95,115,255),BorderSizePixel=0,Text="VALIDAR KEY",TextColor3=Color3.new(1,1,1),TextSize=13,Font=Enum.Font.GothamBold,AutoButtonColor=false})
    rounded(btn,10)
    local status=ui(main,"TextLabel",{Size=UDim2.new(1,-40,0,48),Position=UDim2.fromOffset(20,210),BackgroundTransparency=1,Text="Estado: à espera da key...",TextColor3=Color3.fromRGB(135,141,155),TextSize=11,Font=Enum.Font.Gotham,TextXAlignment=Enum.TextXAlignment.Left})
    local done=false
    local key=nil
    local oneTime=false
    local function go()
        if done then return end
        local k=tostring(box.Text):gsub("^%s+",""):gsub("%s+$",""):upper()
        if k=="" then status.TextColor3=Color3.fromRGB(255,100,100);status.Text="Estado: introduza uma key.";return end
        btn.Text="A VERIFICAR...";btn.Active=false;status.TextColor3=Color3.fromRGB(135,141,155);status.Text="Estado: a contactar o servidor..."
        local ok,info=validate(k)
        if ok then
            done=true;key=k;oneTime=select(3, validate(k)) or false;_G.GustavoHubOneTimeKey=oneTime;_G.GustavoHubLicenseRevoked=false
            status.TextColor3=Color3.fromRGB(53,190,105);status.Text="Estado: key válida."
            task.wait(.25);g:Destroy()
        else
            status.TextColor3=Color3.fromRGB(255,100,100);status.Text="Estado: "..tostring(info);btn.Text="VALIDAR KEY";btn.Active=true
        end
    end
    btn.MouseButton1Click:Connect(go)
    box.FocusLost:Connect(function(enter) if enter then go() end end)
    while not done do task.wait(.1) end
    return key
end

