local function decode(s)
    local chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    s=s:gsub('[^'..chars..'=]','')
    local bytes={}
    local bitstr=s:gsub('.',function(x)
        if x=='=' then return '' end
        local n=chars:find(x,1,true)-1
        local r=''
        for i=6,1,-1 do r=r..((n%2^i-n%2^(i-1)>0) and '1' or '0') end
        return r
    end)
    for byte in bitstr:gmatch('[01][01][01][01][01][01][01][01]') do
        local n=0
        for i=1,8 do if byte:sub(i,i)=='1' then n=n+2^(8-i) end end
        bytes[#bytes+1]=string.char(n)
    end
    return table.concat(bytes)
end

local SOURCES={
    [1]={name="AIM-LOCK",data=""},
    [2]={name="ACTION RECORDER",data=""},
    [3]={name="HITBOX",data=""},
}

local key=keyGui()
if not key then return end

