local function runSelected(index)
    local source=decode(SOURCES[index].data)
    local fn,err=loadstring(source)
    if not fn then error("GUSTAVO HUB: "..tostring(err)) end
    return fn()
end

local running=true
task.spawn(function()
    while running do
        task.wait(RECHECK)
        if not running then break end
        if _G.GustavoHubOneTimeKey == true then
            break
        end
        local ok=validate(key)
        if not ok then
            _G.GustavoHubLicenseRevoked=true
            running=false
            break
        end
    end
end)

return runSelected(selected)
